package com.codeforge.platform.config;

import com.codeforge.platform.entity.OrgMember;
import com.codeforge.platform.entity.Organization;
import com.codeforge.platform.entity.User;
import com.codeforge.platform.mapper.OrgMemberMapper;
import com.codeforge.platform.mapper.OrganizationMapper;
import com.codeforge.platform.mapper.UserMapper;
import org.springframework.boot.CommandLineRunner;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.stereotype.Component;

import java.time.LocalDateTime;

@Component
public class DataInitializer implements CommandLineRunner {

    private final UserMapper userMapper;
    private final OrganizationMapper organizationMapper;
    private final OrgMemberMapper orgMemberMapper;
    private final PasswordEncoder passwordEncoder;

    public DataInitializer(UserMapper userMapper,
                           OrganizationMapper organizationMapper,
                           OrgMemberMapper orgMemberMapper,
                           PasswordEncoder passwordEncoder) {
        this.userMapper = userMapper;
        this.organizationMapper = organizationMapper;
        this.orgMemberMapper = orgMemberMapper;
        this.passwordEncoder = passwordEncoder;
    }

    @Override
    public void run(String... args) {
        User existingAdmin = userMapper.findByUsername("admin");
        if (existingAdmin != null) {
            return;
        }

        LocalDateTime now = LocalDateTime.now();

        User admin = new User();
        admin.setUsername("admin");
        admin.setPassword(passwordEncoder.encode("admin123"));
        admin.setRole("ADMIN");
        admin.setCreatedAt(now);
        userMapper.insert(admin);

        User alice = new User();
        alice.setUsername("alice");
        alice.setPassword(passwordEncoder.encode("alice123"));
        alice.setRole("USER");
        alice.setCreatedAt(now);
        userMapper.insert(alice);

        Organization org = new Organization();
        org.setName("默认团队");
        org.setDescription("系统默认团队");
        org.setOwnerId(admin.getId());
        org.setCreatedAt(now);
        organizationMapper.insert(org);

        OrgMember member = new OrgMember();
        member.setOrgId(org.getId());
        member.setUserId(admin.getId());
        member.setMemberRole("ADMIN");
        member.setJoinedAt(now);
        orgMemberMapper.insert(member);
    }
}

package com.codeforge.platform.config;

import io.jsonwebtoken.Claims;
import io.jsonwebtoken.Jwts;
import io.jsonwebtoken.SignatureAlgorithm;
import io.jsonwebtoken.security.Keys;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

import javax.crypto.SecretKey;
import java.nio.charset.StandardCharsets;
import java.util.Date;

@Component
public class JwtUtil {

    private final SecretKey key;
    private final long expiration;

    public JwtUtil(@Value("${jwt.secret}") String secret,
                   @Value("${jwt.expiration}") long expiration) {
        this.key = Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));
        this.expiration = expiration;
    }

    public String generateToken(String username, String role, Long userId) {
        Date now = new Date();
        Date expiry = new Date(now.getTime() + expiration);

        return Jwts.builder()
                .setSubject(username)
                .claim("role", role)
                .claim("userId", userId)
                .setIssuedAt(now)
                .setExpiration(expiry)
                .signWith(key, SignatureAlgorithm.HS256)
                .compact();
    }

    public Claims parseToken(String token) {
        return Jwts.parserBuilder()
                .setSigningKey(key)
                .build()
                .parseClaimsJws(token)
                .getBody();
    }

    public boolean validateToken(String token) {
        try {
            parseToken(token);
            return true;
        } catch (Exception e) {
            return false;
        }
    }

    public String getUsernameFromToken(String token) {
        return parseToken(token).getSubject();
    }

    public String getRoleFromToken(String token) {
        return parseToken(token).get("role", String.class);
    }

    public Long getUserIdFromToken(String token) {
        return parseToken(token).get("userId", Long.class);
    }
}

package com.codeforge.platform.config;

import com.codeforge.platform.filter.JwtAuthFilter;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.config.http.SessionCreationPolicy;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.security.web.SecurityFilterChain;
import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;

@Configuration
@EnableWebSecurity
public class SecurityConfig {

    private final JwtAuthFilter jwtAuthFilter;

    public SecurityConfig(JwtAuthFilter jwtAuthFilter) {
        this.jwtAuthFilter = jwtAuthFilter;
    }

    @Bean
    public PasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder();
    }

    @Bean
    public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
        http
                .csrf(csrf -> csrf.disable())
                .sessionManagement(session -> session.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
                .authorizeHttpRequests(auth -> auth
                        .requestMatchers("/api/auth/login", "/api/repos/*/readme").permitAll()
                        .anyRequest().authenticated()
                )
                .addFilterBefore(jwtAuthFilter, UsernamePasswordAuthenticationFilter.class);

        return http.build();
    }
}

package com.codeforge.platform.controller;

import com.codeforge.platform.dto.ApiResponse;
import com.codeforge.platform.dto.LoginRequest;
import com.codeforge.platform.dto.LoginResponse;
import com.codeforge.platform.service.AuthService;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/auth")
public class AuthController {

    private final AuthService authService;

    public AuthController(AuthService authService) {
        this.authService = authService;
    }

    @PostMapping("/login")
    public ResponseEntity<ApiResponse<LoginResponse>> login(@RequestBody LoginRequest request) {
        ApiResponse<LoginResponse> response = authService.login(request.getUsername(), request.getPassword());
        return ResponseEntity.ok(response);
    }
}

package com.codeforge.platform.controller;

import com.codeforge.platform.dto.ApiResponse;
import com.codeforge.platform.dto.CreateFileRequest;
import com.codeforge.platform.service.RepoService;
import org.springframework.http.ResponseEntity;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.*;

import java.util.List;
import java.util.Map;

@RestController
@RequestMapping("/api/repos/{repoId}/files")
public class FileController {

    private final RepoService repoService;

    public FileController(RepoService repoService) {
        this.repoService = repoService;
    }

    @PostMapping
    public ResponseEntity<ApiResponse<Map<String, Object>>> createOrUpdateFile(
            @PathVariable Long repoId,
            @RequestBody CreateFileRequest request,
            Authentication authentication) {
        Long userId = (Long) authentication.getPrincipal();
        ApiResponse<Map<String, Object>> response = repoService.createOrUpdateFile(
                repoId, request.getPath(), request.getContent(), userId);
        return ResponseEntity.ok(response);
    }

    @GetMapping
    public ResponseEntity<ApiResponse<List<Map<String, Object>>>> listFiles(
            @PathVariable Long repoId,
            Authentication authentication) {
        ApiResponse<List<Map<String, Object>>> response = repoService.listFiles(repoId);
        return ResponseEntity.ok(response);
